class Node {
  public String text;
  public Node left;
  public Node right;

  public Node(String text) {
    this.text = text;
    this.left = null;
    this.right = null;
  }
}

class HiddenMessage {
  private StringBuilder message;

  private void visit(Node node) {
    if (node == null) {
      return;
    }
    if (node.text.charAt(0) == 'b') {
      message.append(node.text.charAt(1));
      visit(node.left);
      visit(node.right);
    } else if (node.text.charAt(0) == 'i') {
      visit(node.left);
      message.append(node.text.charAt(1));
      visit(node.right);
    } else {
      visit(node.left);
      visit(node.right);
      message.append(node.text.charAt(1));
    }
  }

  public String solve(Node root) {
    message = new StringBuilder();
    visit(root);
    return message.toString();
  }
}

